//! Links elements of the live preview with their place in the source: finds
//! the start tag of an element the user clicked in the page (described by tag,
//! class, attributes and text, so pages generated by PHP work too), and the
//! element around the cursor in the source.

use std::ops::Range;

/// An element as the page describes it.
#[derive(Clone, Debug, Default, PartialEq, Eq, serde::Deserialize, serde::Serialize)]
#[serde(default)]
pub struct ElementSig {
    pub tag: String,
    /// The `class` attribute as written.
    pub cls: String,
    /// Telling attributes (id, href, src, name, …) with their values.
    pub attrs: Vec<(String, String)>,
    /// The element's own text (whitespace collapsed, start only).
    pub text: String,
    /// Position among the page's elements with the same tag and class.
    pub index: usize,
}

const VOID: &[&str] = &["area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"];

/// Value of an attribute in a start tag (`<a href="x" class=y>`).
pub fn attr(tag: &str, name: &str) -> Option<String> {
    let lower = tag.to_ascii_lowercase();
    let mut from = 0;
    while let Some(i) = lower[from..].find(name).map(|i| i + from) {
        from = i + name.len();
        let before_ok = i > 0 && lower.as_bytes()[i - 1].is_ascii_whitespace();
        let rest = lower[from..].trim_start();
        if !before_ok || !rest.starts_with('=') {
            continue;
        }
        let start = tag.len() - rest.len() + 1;
        let value = tag[start..].trim_start();
        let (quote, body) = match value.chars().next() {
            Some(q @ ('"' | '\'')) => (Some(q), &value[1..]),
            _ => (None, value),
        };
        let end = match quote {
            Some(q) => body.find(q).unwrap_or(body.len()),
            None => body.find(|c: char| c.is_whitespace() || c == '>').unwrap_or(body.len()),
        };
        return Some(body[..end].to_string());
    }
    None
}

/// A start or end tag found in the source.
struct Tag {
    /// Byte range of the whole tag (`<` to `>`).
    range: Range<usize>,
    name: String,
    end: bool,
}

/// Iterates over tags, skipping comments, PHP blocks, doctype and the
/// contents of `script`/`style`.
fn tags(src: &str) -> Vec<Tag> {
    let b = src.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while let Some(off) = src[i..].find('<') {
        let at = i + off;
        let rest = &src[at..];
        let skip_to = |pat: &str| rest.find(pat).map_or(src.len(), |e| at + e + pat.len());
        if rest.starts_with("<!--") {
            i = skip_to("-->");
            continue;
        }
        if rest.starts_with("<?") {
            i = skip_to("?>");
            continue;
        }
        if rest.starts_with("<!") {
            i = skip_to(">");
            continue;
        }
        let end = rest.starts_with("</");
        let name_start = at + if end { 2 } else { 1 };
        let name_len = src[name_start..].bytes().take_while(|c| c.is_ascii_alphanumeric() || *c == b'-').count();
        if name_len == 0 || !b[name_start].is_ascii_alphabetic() {
            i = at + 1;
            continue;
        }
        let name = src[name_start..name_start + name_len].to_ascii_lowercase();
        // The end of the tag: the first `>` outside quotes and PHP blocks.
        let mut j = name_start + name_len;
        let mut quote = None;
        while j < b.len() {
            match (quote, b[j]) {
                (None, b'<') if src[j..].starts_with("<?") => j = src[j..].find("?>").map_or(b.len(), |e| j + e + 1),
                (None, b'"' | b'\'') => quote = Some(b[j]),
                (Some(q), c) if c == q => quote = None,
                (None, b'>') => break,
                _ => {}
            }
            j += 1;
        }
        let close = (j + 1).min(src.len());
        out.push(Tag { range: at..close, name: name.clone(), end });
        i = close;
        if !end && (name == "script" || name == "style") {
            let needle = format!("</{name}");
            i = src[i..].to_ascii_lowercase().find(&needle).map_or(src.len(), |e| i + e);
        }
    }
    out
}

fn collapse(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Start tag (byte range) in `src` that best fits the element, with a score
/// (0 = only the tag name fits).
pub fn find_start_tag(src: &str, sig: &ElementSig) -> Option<(Range<usize>, u32)> {
    let tag = sig.tag.to_ascii_lowercase();
    let mut best: Option<(Range<usize>, u32)> = None;
    let mut same_class = 0;
    for t in tags(src).into_iter().filter(|t| !t.end && t.name == tag) {
        let text = &src[t.range.clone()];
        let cls = attr(text, "class").unwrap_or_default();
        let mut score = 0;
        if collapse(&cls) == collapse(&sig.cls) {
            score += 5;
            if same_class == sig.index {
                score += 2;
            }
            same_class += 1;
        } else {
            score += sig.cls.split_whitespace().filter(|c| cls.split_whitespace().any(|x| x == *c)).count() as u32;
        }
        for (name, value) in &sig.attrs {
            match attr(text, name) {
                Some(v) if v == *value => score += if name == "id" { 10 } else { 3 },
                // Generated by PHP, or relative vs. absolute URLs.
                Some(v) if !v.is_empty() && (value.ends_with(&v) || v.contains("<?")) => score += 1,
                _ => {}
            }
        }
        if !sig.text.is_empty() {
            let after = &src[t.range.end..];
            let own = collapse(&after[..after.find('<').unwrap_or(after.len())]);
            if !own.is_empty() && (own.starts_with(&sig.text) || sig.text.starts_with(&own)) {
                score += 4;
            }
        }
        if best.as_ref().is_none_or(|(_, s)| score > *s) {
            best = Some((t.range.clone(), score));
        }
    }
    best
}

/// What the page needs to find the element around `pos` (byte offset).
pub fn element_at(src: &str, pos: usize) -> Option<ElementSig> {
    let all = tags(src);
    let mut stack: Vec<&Tag> = Vec::new();
    let mut inside: Option<&Tag> = None;
    for t in &all {
        // A cursor right before an end tag is still inside its element.
        if t.range.start > pos || t.end && t.range.start == pos {
            break;
        }
        if t.end {
            if let Some(k) = stack.iter().rposition(|s| s.name == t.name) {
                stack.truncate(k);
            }
            continue;
        }
        let text = &src[t.range.clone()];
        let selfclosing = VOID.contains(&t.name.as_str()) || text.ends_with("/>");
        if selfclosing {
            if t.range.contains(&pos) {
                inside = Some(t);
            }
        } else {
            stack.push(t);
        }
    }
    let t = inside.or_else(|| stack.last().copied())?;
    if matches!(t.name.as_str(), "html" | "body" | "head") {
        return None;
    }
    let text = &src[t.range.clone()];
    let cls = attr(text, "class").unwrap_or_default();
    let index = all
        .iter()
        .take_while(|o| o.range.start < t.range.start)
        .filter(|o| !o.end && o.name == t.name && collapse(&attr(&src[o.range.clone()], "class").unwrap_or_default()) == collapse(&cls))
        .count();
    let attrs = attr(text, "id").map(|id| vec![("id".to_string(), id)]).unwrap_or_default();
    Some(ElementSig { tag: t.name.clone(), cls, attrs, text: String::new(), index })
}

/// Where the text `before` of the element starting with the tag at
/// `tag_end` (byte offset after `>`) is in the source, if it is written
/// there as plain text.
pub fn text_range(src: &str, tag_end: usize, before: &str) -> Option<Range<usize>> {
    let after = &src[tag_end..];
    let content_end = after.find('<').unwrap_or(after.len());
    let content = &after[..content_end];
    let wanted = collapse(before);
    if wanted.is_empty() || collapse(&decode(content)) != wanted {
        return None;
    }
    // Keep surrounding whitespace (indentation) as it is.
    let start = content.len() - content.trim_start().len();
    let end = content.trim_end().len();
    Some(tag_end + start..tag_end + end)
}

fn decode(s: &str) -> String {
    s.replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"").replace("&#39;", "'").replace("&nbsp;", "\u{a0}").replace("&amp;", "&")
}

/// Text for the source: `<`, `>` and `&` as entities.
pub fn encode(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
}

#[cfg(test)]
mod tests {
    use super::*;

    const PAGE: &str = r#"<!doctype html>
<html><head><style>p > a { color: red }</style></head>
<body>
  <!-- <div class="nav"> -->
  <nav class="nav">
    <a href="/" class="item">Start</a>
    <a href="/kontakt.php" class="item">Kontakt</a>
  </nav>
  <section id="hero" class="hero big">
    <h1>Willkommen &amp; hallo</h1>
    <img src="logo.png" alt="Logo">
    <p class="lead">Text <?php echo $name; ?> mehr</p>
  </section>
</body></html>"#;

    fn sig(tag: &str, cls: &str, attrs: &[(&str, &str)], text: &str, index: usize) -> ElementSig {
        ElementSig { tag: tag.into(), cls: cls.into(), attrs: attrs.iter().map(|(a, b)| (a.to_string(), b.to_string())).collect(), text: text.into(), index }
    }

    fn found(s: &ElementSig) -> &'static str {
        let (r, _) = find_start_tag(PAGE, s).unwrap();
        &PAGE[r]
    }

    #[test]
    fn finds_clicked_elements() {
        assert_eq!(found(&sig("a", "item", &[("href", "/kontakt.php")], "Kontakt", 1)), r#"<a href="/kontakt.php" class="item">"#);
        // Same attributes: the position among equal elements decides.
        assert_eq!(found(&sig("a", "item", &[], "", 0)), r#"<a href="/" class="item">"#);
        assert_eq!(found(&sig("section", "hero big", &[("id", "hero")], "", 0)), r#"<section id="hero" class="hero big">"#);
        assert_eq!(found(&sig("h1", "", &[], "Willkommen & hallo", 0)), "<h1>");
        // The comment and the stylesheet do not count as tags.
        assert_eq!(found(&sig("nav", "nav", &[], "", 0)), r#"<nav class="nav">"#);
        assert_eq!(found(&sig("img", "", &[("src", "http://nebula.localhost/logo.png"), ("alt", "Logo")], "", 0)), r#"<img src="logo.png" alt="Logo">"#);
    }

    #[test]
    fn element_around_cursor() {
        let at = |needle: &str| element_at(PAGE, PAGE.find(needle).unwrap()).unwrap();
        let e = at("Kontakt<");
        assert_eq!((e.tag.as_str(), e.cls.as_str(), e.index), ("a", "item", 1));
        let e = at("logo.png");
        assert_eq!(e.tag, "img");
        let e = at("mehr");
        assert_eq!((e.tag.as_str(), e.cls.as_str()), ("p", "lead"));
        let e = at("Willkommen");
        assert_eq!(e.tag, "h1");
        // Right before `</a>` of "Start": still in the link.
        assert_eq!(at("</a>\n    <a href=\"/kontakt").tag, "a");
        assert_eq!(at("<section").attrs, vec![("id".to_string(), "hero".to_string())]);
        assert!(element_at(PAGE, PAGE.find("<body>").unwrap() + 7).is_none());
    }

    #[test]
    fn text_in_source() {
        let (r, _) = find_start_tag(PAGE, &sig("h1", "", &[], "Willkommen & hallo", 0)).unwrap();
        let t = text_range(PAGE, r.end, "Willkommen & hallo").unwrap();
        assert_eq!(&PAGE[t], "Willkommen &amp; hallo");
        // Text mixed with PHP or markup is not plain: not edited.
        let (r, _) = find_start_tag(PAGE, &sig("p", "lead", &[], "Text", 0)).unwrap();
        assert_eq!(text_range(PAGE, r.end, "Text Max mehr"), None);
        assert_eq!(encode("a < b & c"), "a &lt; b &amp; c");
        assert_eq!(attr(r#"<a data-x="1" x='2' y=3>"#, "x"), Some("2".into()));
        assert_eq!(attr("<a y=3>", "y"), Some("3".into()));
    }
}
